def read(n):return json.loads((D/n).read_text())
def enc(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
frames={p.stem:enc(p) for p in sorted((D/'frames').glob('*.png'))}
plans={p.stem:p.read_text() for p in sorted((D/'plans').glob('*.svg'))}
O=read('OPERATIONS.json');H=read('SITE_HOLDS.json');I=read('INTEGRATION_HANDOFF.json');P=read('PRESERVATION.json')
previews=[]
for g,f,label in [('group1b','B2-living-to-dining','الاستقبال والمدخل · B2'),('group2','B-BR02-entry','غرف النوم وWIC · B'),('group3','B-master-wide','الحمامات · B'),('group4','RECOMMENDED-work','المطبخ · الترجيح المشروط')]:
 p=ROOT/g/'frames'/f'{f}.png';e=json.loads((ROOT/g/'RENDER_EVIDENCE.json').read_text());r=next(r for r in e['frames'] if r['frame_id']==f);assert hashlib.sha256(p.read_bytes()).hexdigest()==r['png_sha256'];frames['INTEGRATION-'+g]=enc(p);previews.append(dict(group=g,frame='INTEGRATION-'+g,label=label,png_sha256=r['png_sha256'],source_path=str(p)))
dimensions=''.join(f'<tr><td>{r["id"]}</td><td>{r["printed_text"].replace("TERRACE ","")}</td><td>{r["polygon_extents_mm"][0]:.0f} × {r["polygon_extents_mm"][1]:.0f}</td><td>{r["difference_polygon_minus_printed_mm"][0]:+.0f} / {r["difference_polygon_minus_printed_mm"][1]:+.0f}</td><td>{r["nominal_face_extents_mm"][0]:.0f} × {r["nominal_face_extents_mm"][1]:.0f}</td></tr>' for r in O['rooms'])
holds=''.join(f'<details><summary><b>{h["id"]} · {h["title"]}</b><span>{h["priority"]} / OPEN</span></summary><p>{h["required_evidence"]}</p><p class="muted">المراجعة: {h["professional"]}</p></details>' for h in H['holds'])
inherited=''.join(f'<p><b>{p["ids"][0].split("-H")[0]}</b> · {len(p["ids"])} بوابات مستقلة مفتوحة · <code>{p["sha256"]}</code></p>' for p in H['inherited'])
grid=''.join(f'<article><img data-frame="{p["frame"]}" alt="{p["label"]}"/><h3>{p["label"]}</h3><a href="https://github.com/Mostafatalaat770/flat-designer/raw/type-b-m3-group5-review-20261012/design-development/whole-home-m3/{p["group"]}/Owner-Review.html">المراجعة الأصلية</a></article>' for p in previews)
storage_ar=[('Group1B','البوفيه يخسر 38.3% من عرض داخلي مفترض؛ تخزين أحذية المدخل والجرد لم يُحسما.'),('Group2','دولاب BR02 يخسر 25% خارجيًا و25.9% من عرض صافي مفترض؛ أدراج الماستر وBR01 تخسر 41.7% من عرض مفترض. حيز الأحذية الاحتياطي في WIC غير مخصص.'),('Group3','خزانة الأسرة 520×170 مم بعمق داخلي مفترض 134 مم لمناشف اليد فقط؛ مناشف الجسم والمفروشات تحتاج مكانًا محددًا.'),('Group4','علوي A بداخل مفترض 1764×294×664 مم يعطي ≈344.36 لتر إجماليًا هندسيًا؛ خانة B المفتوحة 300 مم تنقص ≈58.57 لتر من الإغلاق المفترض. ليس صافيًا، والركن الأعمى رصيده اليومي صفر لحين إثبات الوصول.'),('Group5','صندوق أدوات محمول فقط؛ لا مخزن خارجي معتمد. مكان المنشر المطوي داخل البيت يحتاج تخصيصًا بعد الجرد.')]
storage_rows=''.join('<tr><td>'+g+'</td><td>'+v+'</td><td>غير محسوم</td></tr>' for g,v in storage_ar)
page=r'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'none'; base-uri 'none'; form-action 'none'"><title>Type B · التراسات الثلاثة · M3 Group5</title><style>
:root{--ink:#283c32;--sage:#6c7d64;--cream:#f3f0e6;--paper:#fffdf8;--line:#d9ded1;--clay:#a77556}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font:17px/1.85 Tahoma,Arial,sans-serif}a{color:#496e58}header{padding:42px max(5vw,20px) 22px;background:#263d32;color:#f9f6ed}header p{max-width:920px;color:#dde2d5}h1{font-size:clamp(30px,4vw,58px);line-height:1.4;margin:10px 0}h2{font-size:30px;line-height:1.5;margin:0 0 16px}h3{font-size:21px;margin:12px 0 5px}p{margin:10px 0}.eyebrow{letter-spacing:2px;font-size:13px}.chip{display:inline-block;padding:5px 12px;border:1px solid #adb5a4;border-radius:24px;margin:3px;font-size:14px}nav{position:sticky;top:0;z-index:4;display:flex;gap:10px;overflow:auto;padding:12px 5vw;background:#f8f6eeeF;border-bottom:1px solid var(--line);backdrop-filter:blur(12px)}nav a{white-space:nowrap;text-decoration:none;font-size:15px}main{max-width:1400px;margin:auto;padding:22px 4vw 60px}section{margin:24px 0;padding:28px;background:var(--paper);border:1px solid var(--line);border-radius:18px;scroll-margin-top:65px}button,select{font:inherit;color:var(--ink);border:1px solid #aab6a2;border-radius:9px;background:#fafbf5;padding:9px 15px;cursor:pointer;max-width:100%}button[aria-pressed=true]{color:white;background:#567057}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #b88764;outline-offset:4px}.controls{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:14px 0}.frame{margin:18px 0;border-radius:12px;overflow:hidden;background:#e8e9df}.frame img{width:100%;height:auto;display:block;aspect-ratio:16/9}.frame figcaption{padding:14px 18px;font-size:15px;line-height:1.7;background:#edf0e7}.facts,.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.facts article,.cards article{padding:18px;background:#edf0e7;border-radius:12px}.facts b{font-size:27px;display:block}.note{padding:16px 20px;border-right:4px solid var(--sage);background:#edf0e7;margin:18px 0}.hold{border-color:var(--clay);background:#f4e9dc}.muted{color:#667461;font-size:15px}.table{overflow:auto}table{border-collapse:collapse;width:100%;min-width:700px;font-size:15px}th,td{text-align:right;padding:13px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#e6ebdf}.plan-box{border:1px solid var(--line);background:#f9f8f3;border-radius:12px;overflow:auto;direction:ltr}.plan-box svg{display:block;width:100%;height:auto;min-width:700px}.plan-box.zoom svg{width:1500px;max-width:none}.palette{display:flex;gap:12px;flex-wrap:wrap}.swatch{display:flex;align-items:center;gap:9px;padding:8px;background:#f0f2e9;border-radius:8px}.swatch i{width:36px;height:36px;display:block;border-radius:50%;border:1px solid #b3b9a7}details{border:1px solid var(--line);padding:13px 17px;border-radius:10px;margin:9px 0}summary{cursor:pointer;display:flex;justify-content:space-between;gap:10px}summary span{font-size:13px;white-space:nowrap}.book-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.book-grid img{width:100%;border-radius:10px}.book-grid article{padding:12px;background:#edf0e7;border-radius:12px}code{direction:ltr;unicode-bidi:embed;font:12px/1.5 monospace;overflow-wrap:anywhere}footer{padding:20px;text-align:center;color:#697560;font-size:14px}.split{display:grid;grid-template-columns:1fr 1fr;gap:18px}.split img{width:100%;border-radius:10px}@media(max-width:750px){body{font-size:16px}header{padding:26px 20px}main{padding:12px}section{padding:18px 15px;margin:16px 0}.facts,.cards,.book-grid,.split{grid-template-columns:1fr}.plan-box svg{min-width:650px}h2{font-size:25px}summary{flex-wrap:wrap}.controls button{font-size:14px;padding:8px 10px}}@media print{nav,.controls{display:none}section{break-inside:avoid}body{background:white}.plan-box svg{min-width:0!important}details{display:block}summary{display:block}}
</style></head><body><header><div class="eyebrow" dir="ltr">TYPE B / M3 GROUP5 / 12 OCTOBER 2026 · CAIRO</div><h1>ثلاث تراسات.<br>قعدة خفيفة، وراحة محسوبة.</h1><p>امتداد هادي للبيت: خشب دافئ، زيتوني رمادي، حجر مطفي وخضرة محدودة. الترجيح: قعدة لشخصين في الرئيسي، ركن واحد للماستر، ونشر صغير قابل للطي في الخدمة.</p><span class="chip">مراجعة تصميم مبدئية</span><span class="chip">24 لقطة WebGL فعلية · 7 كاميرات متطابقة</span><span class="chip">10 مخططات مقاسة</span><span class="chip">40 HOLD سابقة + 12 جديدة مفتوحة</span></header>
<nav aria-label="أقسام المراجعة"><a href="#lead">الترجيح</a><a href="#dimensions">الأبعاد</a><a href="#main">الرئيسي</a><a href="#master">الماستر</a><a href="#service">الخدمة</a><a href="#materials">الخامات والصيانة</a><a href="#critique">النقد والتصحيح</a><a href="#holds">الموقع والمختصون</a><a href="#integration">تكامل البيت</a></nav><main>
<section id="lead"><h2>راحة يومية قبل زيادة عدد القطع</h2><div class="facts"><article><b>شخصان</b>الرئيسي A: كرسيان بذراع، طاولة 600 مم بارتفاع بصري 520 مم، صينية شاي وفانوس صغير منفصل عنها.</article><article><b>شخص واحد</b>الماستر: كرسي خفيف، النبات الأصلي، وصينية ذراع للكوب والضوء. الأرض خالية من لمبة أو طاولة إضافية.</article><article><b>نشر ثم طي</b>الخدمة B: منشر رأسي 600×500 مم مبدئيًا، وصندوق أدوات محمول. يطوى ويُحفظ داخل البيت بعد الاستخدام.</article></div><p class="note hold">كل القياسات من النموذج. الحاجز الظاهر 1000 مم ليس قياس موقع أو شهادة أمان، وترتيب الكراسي والأصص والمنشر يحتاج مراجعة سقوط/تسلق وثبات وأحمال. لا اعتماد تنفيذ أو منتج أو شراء أو حفظ سحابي.</p></section>
<section id="dimensions"><h2>المطبوع والمضلع والمساحة الصافية</h2><p>الاختلافات محفوظة كما هي. عمود الصافي التخطيطي يخصم 90 مم عند كل حد، اعتمادًا على جدار/حاجز مصدر بسُمك 180 مم ومركزه على الحدود. يشمل الخصم حد الفتحة تحفظًا؛ ليس رفعًا صافيًا للتشطيب أو مساحة استعمال مضمونة.</p><div class="table"><table><thead><tr><th>التراس</th><th>الأبعاد المطبوعة</th><th>امتداد المضلع X×Y مم</th><th>فرق X / Y مم</th><th>نطاق وجوه اسمي مم</th></tr></thead><tbody>__DIMENSIONS__</tbody></table></div><p class="muted">طابقنا البُعد المطبوع الأكبر بالمحور الأطول للمقارنة، دون افتراض اتجاه جغرافي أو تصحيح المصدر. عرض المسارات، الإطارات، مناسيب العتبات والصرف والكسوات يقاس في الموقع. اسم أرضية المصدر antislip لا يثبت مقاومة الانزلاق. في المخططات: داكن للجدار، زيتوني للحاجز، أخضر متقطع للجسم المفترض وخط للمسار عند نجاحه. كل أرقام الفراغ بالملليمتر. نتائج 20/25 مم متوافقة؛ شبكة 50 مم حجبت بدايات في بعض الحالات حتى دون أثاث. ده أثر تحفظ الشبكة مسجل، وليس دليل انسداد فعلي.</p><div class="facts"><article><b>≈923 مم</b>جزء الدخول المتاح نظريًا من زجاج الرئيسي 1885 مم: نصفه، بعد خصم طرف إطار النموذج 20 مم.</article><article><b>≈668 مم</b>مدخل الماستر من زجاج 1377 مم. ليس فتحة كاملة العرض؛ نقل الكرسي والإطار والمقبض تجربة مورّد وموقع.</article><article><b>≈658 مم</b>حد ضلفة الخدمة 678 مم مع نصف سُمك ضلفة 40 مم عند الفتح. المقابض والإطار غير محسومين. الضلفة تفتح شمال الرسم داخل المطبخ.</article></div></section>
<section id="main"><h2>الرئيسي · طقس قهوة هادي</h2><p>كرسيان مفتوحا الهيكل يتركان الفراغ مقروءًا من الاستقبال، وطاولة دائرية مطفية تجمعهما. نبات واحد منخفض بجوار الجدار الكامل بدل شريط أصص يزاحم المشي. الجدار الغربي العالي والحاجز والفتحة الأصلية محفوظون.</p><div class="controls" data-controls="main"></div><figure class="frame"><img id="main-image" alt="مقارنة فعلية للتراس الرئيسي"/><figcaption id="main-caption"></figcaption></figure><p class="note">A هو الترجيح. B يحسن ارتفاع الطاولة للمحادثة والضيافة، لكن الكرسي الثالث يشغل منطقة انتقال كانت خالية. مع سحبه 200 مم يتبقى ≈13 مم فقط خلفه عند وجه الزجاج الاسمي؛ استخدام عرضي مع إزالته بعدها، لا قعدة دائمة لثلاثة.</p><div class="cards"><article><h3>الشاي والوصول</h3>صينية 350×250 مم وكوبان بحجم تمثيلي. للفانوس حيز مستقل: 24 مم عن حافة الصينية و39 مم عن حافة دائرة A. الوصول لمنتصف الطاولة يحتاج تجربة اليد والركبة وارتفاع المقعد؛ لا اعتماد مقاس منتج.</article><article><h3>الوقوف والمرور</h3>في A وجدنا مسار جسم دائري افتراضي 500/600 مم إلى نقطة الوقوف الغربية، حتى مع أغلفة نهوض محددة. B يضيّق نفس نقطة الوقوف. هذا اختبار نقاط وافتراضات بشبكات 20/25/50 مم، وليس حكمًا أن أي قعدة لثلاثة مستحيلة أو مرورًا قانونيًا معتمدًا.</article><article><h3>الزجاج والستارة</h3>الضلفة المتحركة تقف فوق اليسرى وتترك يمين الفتحة للدخول. الستارة الأصلية من الداخل بقيت كما هي؛ تراكمها الحقيقي يتراجع مع نجارة B2 وبوّابات Group1B. لا سلك أو حافة سجادة تعبر المسار.</article></div><p>الصورة الليلية تدرس جو الطاولة فقط. الضوء المحمول لا يثبت إضاءة الأرض أو أمان المسار أو منع الوهج للجيران؛ اختبار مسائي فعلي ضروري. لا مصباح سقف، سقف جديد أو افتراض موقع مكثف.</p><div class="controls"><label for="main-plan">مخطط التشغيل</label><select id="main-plan"></select><button data-zoom="main">تكبير المخطط</button></div><div class="plan-box" id="main-plan-box"></div></section>
<section id="master"><h2>الماستر · ركن واحد، وفوضى أقل</h2><p>كرسي بذراع ووسادة زيتونية صغيرة، والنبات الأصلي في أصيص قابل للنقل. صينية الذراع تجمع كوبًا وفانوسًا صغيرًا وتوفر أرضية سهلة المسح. المقاس التخطيطي للكرسي 580×600 مم، ومطابقة منتج بعينه غير معتمدة.</p><div class="controls" data-controls="master"></div><figure class="frame"><img id="master-image" alt="التراس الخاص بالماستر من نفس الكاميرا"/><figcaption id="master-caption"></figcaption></figure><div class="cards"><article><h3>خصوصية واقعية</h3>النبات عنصر منظر أمامي، لا حاجز مثبت ضد الجيران. نحتاج صور وخطوط رؤية من جلوس ووقوف ومقابلها المباني الفعلية قبل ادعاء الخصوصية. لا ساتر أو تعديل واجهة مفترض.</article><article><h3>دخول وتعتيم</h3>المسار الداخلي بلا شخص ثابت ينجح مع فرض 500/600 مم. دخول شخص آخر أثناء نهوض الجالس يضيّق نقطة الاقتراب المختبرة؛ الركن لشخص واحد. أغلق الضوء بعد الاستخدام واختبر blackout وحواف الستارة، مع بقاء HOLDs غرفة النوم كما هي.</article><article><h3>نظافة وطقس</h3>وسادة قابلة للفك تُحفظ داخلًا عند المطر والغبار أو الريح، ومقعد يسهل رفعه. لا وزن رطب معلوم للأصيص ولا صرف محدد على الرسم. قبل الغسيل تُنقل كل القطع لفحص الأرض والصرف القائم.</article></div><div class="controls"><label for="master-plan">مخطط واحد ومصدره</label><select id="master-plan"></select><button data-zoom="master">تكبير المخطط</button></div><div class="plan-box" id="master-plan-box"></div></section>
<section id="service"><h2>الخدمة · عملية، وقابلة للإخلاء</h2><p>الغسالة تبقى K3-laundry-niche في مكانها الداخلي الأصلي. لا خط مياه، مصرف، مكثف أو ريزر يتحرك. التراس للنشر المؤقت وتنظيم أدوات بسيطة، وليس مخزنًا منزليًا إضافيًا.</p><div class="controls" data-controls="service"></div><figure class="frame"><img id="service-image" alt="تراس الخدمة والنشر الفعلي في النموذج"/><figcaption id="service-caption"></figcaption></figure><div class="table"><table><thead><tr><th>النشر المقارن</th><th>A أفقي</th><th>B رأسي · الترجيح المشروط</th></tr></thead><tbody><tr><td>البصمة التخطيطية</td><td>900×450 مم</td><td>600×500 مم</td></tr><tr><td>ارتفاع جسم العرض</td><td>≈950 مم</td><td>≈1280 مم؛ يحتاج تدقيق الثبات والريح</td></tr><tr><td>مستخدم افتراضي 600×600 شرق المنشر</td><td>≈100 مم متبقية حتى الوجه الشرقي</td><td>≈435 مم متبقية</td></tr><tr><td>مسار داخل التراس وقت النشر</td><td>500 مم وجد؛ 600 مم نقطة بداية محجوبة</td><td>500/600 مم وجدا عند نقاط المقارنة</td></tr><tr><td>مطويًا</td><td colspan="2">عمق 120 مم فرضي، ومسار 500/600 مم وجد. لا يثبت انتقال المنشر الحقيقي أو أبعاد طيه في كل الاتجاهات.</td></tr></tbody></table></div><p class="note hold">B يوفر وصولًا أوسع، لكن عرضه الأصغر لا يثبت استقرارًا أفضل. موضع المنشر بالنسبة للحاجز، خطر التسلق، حمل الملابس والريح كلها HOLD. لا حبال أو تثبيت بالحاجز. جرّب سلة ومستخدمًا ومنشرًا حقيقيًا، واحتفظ به داخل البيت بعد الطي.</p><p>الصندوق المحمول 280×280 مم يحتفظ بدلو صغير وأدوات قابلة للتنظيف بعد مطابقة حجمها. تجف الأدوات قبل الغطاء، ولا نحسبه مخزن كيماويات أو سعة مفروشات معتمدة. أغلفة التحميل تناسب شخصًا واحدًا؛ دخول شخص ثان أثناء وقوف مستخدم 600×600 مم يحجب نقطة الاقتراب في النموذج لكلا الخيارين. المخطط المفتوح يظهر المستخدم والحالة المشغولة، وليس مرورًا متزامنًا معتمدًا. طول قضبان الرسم الإجمالي ليس قدرة تحميل أو كفاية ملابس أسرة؛ ملاءة كاملة وحمل مبلل واختبار تباعد الهواء لم يتحققوا.</p><p>باب الخدمة يدخل المطبخ: عدم اصطدامه بمنشر الخارج لا يغلق تعارضه مع الأدراج وغسالة الأطباق والمستخدم داخلًا. تظل G4-H04/H05/H11 مفتوحة. اترك مسارات الهواء القائمة؛ لا أداء تهوية أو مسار تكييف مثبت.</p><div class="controls"><label for="service-plan">المصدر والنشر والطي</label><select id="service-plan"></select><button data-zoom="service">تكبير المخطط</button></div><div class="plan-box" id="service-plan-box"></div></section>
<section id="materials"><h2>خامات تُكمل البيت وتتحمل الخدمة</h2><div class="palette"><span class="swatch"><i style="background:#AC9274"></i>خشب دافئ محدود</span><span class="swatch"><i style="background:#666F62"></i>معدن زيتوني رمادي</span><span class="swatch"><i style="background:#879078"></i>نسيج أخضر هادي</span><span class="swatch"><i style="background:#D3CABB"></i>سطح حجري مطفي</span><span class="swatch"><i style="background:#C8C3B7"></i>أرضية رمادية دافئة</span></div><p>المقارنة A/B تغير نوع الجلسة وارتفاع الطاولة وبصمة المنشر، مع نفس العائلة اللونية؛ الهدف تقييم قرارات مفيدة. لون وأثر الأرضية تمثيل مادة، والجدار والحاجز بكسوتهما الأصلية. لا سماكات بناء أو شبكة فواصل أو طبقة عزل معتمدة.</p><div class="cards"><article><h3>سطح وأطراف</h3>عينات حجر/بورسلين خارجي مطفي، أطراف مريحة بلا حد حاد، ومقارنة مبتلة مع غبار. التقاء الأرض والعتبة والفواصل المرنة ومعالجة رفع الماء يتحدد بعد رفع المناسيب؛ اللون المتقارب لا يعني عتبة مستوية.</article><article><h3>خشب ونسيج ومعدن</h3>اختبر خشبًا/بديله بعينة وصيانة يقدر عليها المالك، نسيجًا قابلًا للفك والتجفيف ومقاومة UV موثقة، ومعدنًا ووصلات مناسبة للتعرض الفعلي. طلاء جميل أو roughness في الرسم لا يثبت مقاومة الصدأ أو الحرارة.</article><article><h3>إضاءة بسيطة</h3>فانوس محمول مع غطاء علوي بصري، تشغيل مستقل، تخزين داخلًا دون شحن مكشوف في المطر أو سلك فوق العتبة. تحديد الحماية والمأخذ أو أي تثبيت للواجهة عمل الكهربائي والمطور؛ لا IP أو lux أو اتجاه شمسي مختلق.</article></div><h3>روتين صيانة يناسب قعدة قليلة القطع</h3><p>بعد الاستخدام: أزل الصينية والفانوس والوسائد والمنشر، واترك السطح خاليًا. دوريًا: ارفع الأصص لفحص الماء والغبار، وامسح الزجاج من جهة يمكن الوصول إليها بأمان دون تجاوز الحاجز، ونظّف الصرف القائم بعد تحديده فعليًا. الري يدوي مضبوط وصحن لا يحتجز ماء راكد؛ لا runoff للواجهة أو الجيران. صنف النبات بعد رؤية ساعات الشمس والريح والحرارة والتراب، ولا تعتمد نوعًا من شكل الأوراق في النموذج.</p></section>
<section id="critique"><h2>النقد والتصحيح ثم إعادة التصوير</h2><div class="split"><figure class="frame"><img data-frame="INITIAL-main-eye" alt="التجربة الأولى الفعلية"/><figcaption>الأولى: نبات 1500 مم ثقيل بصريًا، وفانوس داخل حيز التقديم.</figcaption></figure><figure class="frame"><img data-frame="A-main-eye" alt="التصحيح النهائي من نفس الكاميرا"/><figcaption>النهائية: نبات 950 مم أخف، وفانوس مدمج على حيز منفصل، ونفس هندسة المصدر والكاميرا.</figcaption></figure></div><p>فحص حدود المجسم كشف أيضًا غوص رجل المنشر التجريبية ≈4 مم تحت الأرض؛ رُفع طرفها في المجسم دون تغيير البلاطة، وأُعيد التصوير. الضوء الأرضي في الماستر أُزيل لصالح صينية الذراع. تحسّن الصورة لا يثبت آلية طي أو ثبات منشر أو ضوءًا آمنًا.</p><p>المرفوض: كرسي ثالث دائم ملتصق بمسار الزجاج، نباتات مرتفعة بوصفها حل خصوصية مؤكدًا، سقف أو مظلة إنشائية مختلقة، غسالة خارجية أو تعديل صرف/مكثف، وإضافة مخزن للتعويض عن خسائر غرف أخرى. الصورة الليلية تبقى مظلمة في أجزاء من الأرض؛ هذا سبب لاختبار إنارة موقع، وليس رفع شدة مصباح تجريبي إلى «اعتماد».</p></section>
<section id="holds"><h2>ما يجب حسمه في الموقع</h2><p>12 بوابة جديدة مفتوحة، مع الأربعين السابقة دون أي تغيير. P0 قبل اعتماد موضع أو تنفيذ، وP1 قبل إنهاء الخامة/الاستخدام. كل بوابة تحتاج الدليل المحدد وتوقيع الممارس المصري المختص؛ تنفيذ البيت يظل ضمن Issue #19.</p>__HOLDS__<details><summary>الأربعون بوابة السابقة · محفوظة بايتًا</summary>__INHERITED__</details></section>
<section id="integration"><h2>مدخل مراجعة البيت المتكاملة · القائمة #72</h2><p>كل الغرف الـ13 لها مراجعات مصدرية مستقلة الآن. هذه الصور فهرس للنتائج المسلّمة فعلًا، وليست لقطة لشقة دُمجت خياراتها أو اعتمادًا تلقائيًا للتكوينات. التالي هو كتاب مالك موحد في العمل القائم #72، مع بقاء خريطة المالك #41 كما هي.</p><div class="book-grid">__GRID__</div><h3>اتجاه واحد، مع اختلاف مناسب للاستعمال</h3><p>عاجي وحجر دافئ، أخضر زيتوني محدود وخشب دافئ: كرر العلاقة اللونية، لا نفس مادة حائط الحمام على كل الواجهات. في المطبخ حافظ على R4 ivory / R5 D1 / R6 L2 كترجيح بصري. طبقات إضاءة الوجه والعمل والقراءة والليل لها تحكم مستقل؛ المخطط الكهربائي والتهوية لم يُعتمدا.</p><h3>ميزانية التخزين الواقعية · الإجمالي غير معروف</h3><div class="table"><table><thead><tr><th>المجموعة</th><th>السعة والفجوة المسجلتان</th><th>إجمالي صافي معتمد</th></tr></thead><tbody>__STORAGE__</tbody></table></div><p class="note">صفر سعة منزلية إضافية معتمدة من التراسات. مكان حفظ المنشر المطوي داخلًا يحتاج تخصيصًا بالجرد؛ لا يُسند تلقائيًا إلى WIC أو المطبخ. اجمع أحجام وأعداد المحتويات، ثم مقاسات الداخل والفتحات بعد المفصلات والسيفون والخدمات، وخصّص كل قطعة مرة واحدة وأظهر العجز. لا تجمع لترات خارجية أو نسب عرض مختلفة بوصفها إجماليًا صافيًا.</p><h3>الأولوية التالية للمراجعة</h3><p>① رفع الفتحات والخدمات والمناسيب والحواجز والأحمال. ② تدقيق العزل والكهرباء والتهوية مع المختصين. ③ جرد وتوزيع التخزين فعليًا. ④ إعادة اختبار التكوين المختار عبر الغرف: السفرة والستارة ومدخل الرئيسي، blackout الماستر ورطوبة WIC، وباب الخدمة مع المطبخ. ⑤ عينات وإضاءة ومشاهد خصوصية وصيانة ثم قرارات المالك المبدئية. لا دفعة جديدة من خارطة طريق ولا بحث SKU أو شراء تلقائي.</p><p class="muted">INTEGRATION_HANDOFF.json / .md يجهّزان هذه المدخلات. الكتاب النهائي للتكامل واختبار مشهد موحد يتبعان #72؛ كل اعتماد إنشائي منفصل في #19.</p></section>
<section><h2>مصدر واضح ومراجعة تعمل دون إنترنت</h2><p>صور فعلية من Three.js/WebGL للنموذج المحفوظ، بكاميرات واحدة للمصدر والبدائل. الكاميرات الخارجية جديدة مشتقة من مواقع النموذج وليست كاميرات قديمة محفوظة. لم تُضف مبانٍ مجاورة أو سقوف أو مناخ مؤكد. المخططات تحفظ المضلعات والحوائط والزجاج والباب الأصلي.</p><p>24 PNG أصلية 1280×720، و10 SVG مقروءة؛ الكاميرا وهندسة العمارة متطابقتان في كل مقارنة. 1346 ملفًا سابقًا محفوظ بايتًا، بما فيها المصدر والـmaster plan والحزم وقرارات المالك. الأدوات تتحقق محليًا؛ لا GitHub Actions أو ادعاء CI سحابي. افتح هذا HTML بعد فك ZIP؛ صور ومخططات مدمجة، وروابط المراجعات السابقة تحتاج إنترنت فقط عند فتحها.</p><p><code>canonical: 734b1c36570f27baa930eec481eb109906a1f81684e6fb8f8b6a679fec2b9658<br>source v55: ec05e4fe7c0e15b3555107da4ac5628894df7fcddb3cee996d3af2fddaa7df63<br>parent: d5ee78da71d97cc86b965d52534456a8d4cda7a3</code></p></section>
</main><footer>Type B · M3 Group5 · مراجعة تصميم للمالك · جميع الموافقات HOLD</footer><script>const IMAGES=__IMAGES__;const PLANS=__PLANS__;
const GROUPS={main:{views:[['main-eye','من القعدة'],['main-inside','من الاستقبال'],['main-night','ليل']],options:[['SOURCE','المصدر'],['A','A · شخصان'],['B','B · ثلاثة عرضيًا']],planIds:['TER-MAIN-A','TER-MAIN-B','TER-MAIN-SOURCE'],view:'main-eye',option:'A'},master:{views:[['master-eye','نهار'],['master-night','ليل']],options:[['SOURCE','المصدر'],['A','تركيب واحد']],planIds:['TER-MBR-A','TER-MBR-SOURCE'],view:'master-eye',option:'A'},service:{views:[['service-eye','من الباب'],['service-kitchen','نحو المطبخ']],options:[['SOURCE','المصدر'],['A','A · أفقي'],['B','B · رأسي']],planIds:['TER-SVC-B-DEPLOYED','TER-SVC-B-FOLDED','TER-SVC-A-DEPLOYED','TER-SVC-A-FOLDED','TER-SVC-SOURCE'],view:'service-eye',option:'B',folded:false}};
function draw(name){const g=GROUPS[name];let opt=g.option;if(name==='service'&&g.folded&&g.option!=='SOURCE'&&g.view==='service-eye')opt+='-FOLDED';const id=opt+'-'+g.view;document.getElementById(name+'-image').src=IMAGES[id];document.getElementById(name+'-caption').textContent=(g.options.find(o=>o[0]===g.option)?.[1]||g.option)+' · '+g.views.find(v=>v[0]===g.view)[1]+(name==='service'&&g.folded?' · مطوي، لقطة فعلية من نفس الكاميرا':'')+' · '+id+' · المصدر والكاميرا محفوظان؛ كل التفاصيل مبدئية';document.querySelectorAll('[data-controls="'+name+'"] button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.option?b.dataset.option===g.option:b.dataset.view?b.dataset.view===g.view:g.folded)));}
for(const [name,g] of Object.entries(GROUPS)){const ctl=document.querySelector('[data-controls="'+name+'"]');for(const [id,label] of g.options){const b=document.createElement('button');b.textContent=label;b.dataset.option=id;b.onclick=()=>{g.option=id;g.folded=false;draw(name)};ctl.append(b)}for(const [id,label]of g.views){const b=document.createElement('button');b.textContent=label;b.dataset.view=id;b.onclick=()=>{g.view=id;g.folded=false;draw(name)};ctl.append(b)}if(name==='service'){const b=document.createElement('button');b.textContent='فتح / طي المنشر';b.dataset.fold='1';b.onclick=()=>{g.view='service-eye';if(g.option==='SOURCE')g.option='B';g.folded=!g.folded;draw(name)};ctl.append(b)}const select=document.getElementById(name+'-plan');for(const p of g.planIds){const o=document.createElement('option');o.value=p;o.textContent=p;select.append(o)}select.onchange=()=>document.getElementById(name+'-plan-box').innerHTML=PLANS[select.value];select.onchange();draw(name)}document.querySelectorAll('[data-frame]').forEach(i=>i.src=IMAGES[i.dataset.frame]);document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{const on=document.getElementById(b.dataset.zoom+'-plan-box').classList.toggle('zoom');b.textContent=on?'عرض المخطط كاملًا':'تكبير المخطط';b.setAttribute('aria-pressed',String(on))});
</script></body></html>'''
for k,v in {'__DIMENSIONS__':dimensions,'__HOLDS__':holds,'__INHERITED__':inherited,'__GRID__':grid,'__STORAGE__':storage_rows,'__IMAGES__':json.dumps(frames,ensure_ascii=False),'__PLANS__':json.dumps(plans,ensure_ascii=False)}.items():page=page.replace(k,v)
